using System;
class Program
{
    public static void Main(string[] args)
    {
        using var sr = new System.IO.StringReader("fiz\nbar");
        var r = (sr.ReadLine(), sr.ReadLine()) switch
        {
            ("fiz", "bar") => "Yep, all good!",
            var (a, b) => $"Wait, what? I got ({a}, {b})!",
        };
        Console.WriteLine(r);
    }
}
